namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 uppercase letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    IReadOnlyList<Department> GetDepartments();
    Department? GetDepartment(int id);
    IReadOnlyList<Course> GetCourses(string? searchTerm = null, int? departmentId = null);
    IReadOnlyList<Course> GetFeaturedCourses();
    Course? GetCourse(int id);
    bool SubmitEnrollmentRequest(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Pure and applied mathematics, statistics, and data analysis." },
        new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 4, Name = "English", Code = "ENG", Description = "Literature, writing, and language studies." },
        new() { Id = 5, Name = "Biology", Code = "BIO", Description = "Study of living organisms and life processes." },
    ];

    private static readonly List<Course> Courses =
    [
        new() { Id = 1, Title = "Introduction to Programming", Code = "CS 101", Description = "Foundational course covering programming concepts using Python. Topics include variables, control flow, functions, data structures, and basic object-oriented programming.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of teaching experience and specializes in programming education. She received her Ph.D. from MIT and has published extensively on introductory CS pedagogy.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 2, Title = "Data Structures & Algorithms", Code = "CS 201", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (sorting, searching, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park is a former software engineer at Google with expertise in algorithm optimization. His research focuses on efficient data processing for large-scale systems.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 3, Title = "Database Systems", Code = "CS 340", Description = "Principles of database design, SQL, normalization, transaction management, and an introduction to NoSQL databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Maria Gonzalez", InstructorBio = "Dr. Gonzalez worked in industry for a decade building enterprise database solutions before joining academia. She holds multiple patents in query optimization.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
        new() { Id = 4, Title = "Calculus I", Code = "MATH 151", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Liu", InstructorBio = "Dr. Liu is an award-winning educator known for making calculus accessible. He has authored two popular textbooks on introductory mathematics.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
        new() { Id = 5, Title = "Linear Algebra", Code = "MATH 220", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to data science and machine learning.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Aisha Patel", InstructorBio = "Dr. Patel's research bridges pure mathematics and machine learning. She collaborates with the CS department on interdisciplinary data science projects.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
        new() { Id = 6, Title = "Probability & Statistics", Code = "MATH 360", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Thomas Wright", InstructorBio = "Dr. Wright is a statistician with consulting experience in biotech and finance. He emphasizes real-world data analysis in his teaching.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
        new() { Id = 7, Title = "General Physics I", Code = "PHYS 101", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions with hands-on experiments.", Credits = 4, Schedule = "Tue/Thu 9:00–10:20 AM + Lab Fri 2:00–4:50 PM", InstructorName = "Dr. Emily Nakamura", InstructorBio = "Dr. Nakamura is an experimental physicist whose research focuses on condensed matter. She brings real laboratory experience to her teaching.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true },
        new() { Id = 8, Title = "Quantum Mechanics", Code = "PHYS 301", Description = "Wave functions, Schrödinger equation, quantum states, and applications to atomic and molecular systems.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", InstructorName = "Dr. David Kim", InstructorBio = "Dr. Kim is a theoretical physicist who has published over 50 papers on quantum information theory. He makes abstract quantum concepts tangible through visualization techniques.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false },
        new() { Id = 9, Title = "Creative Writing", Code = "ENG 215", Description = "Workshop-based course exploring fiction, poetry, and creative nonfiction. Students develop a portfolio of original work.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", InstructorName = "Prof. Rachel Adams", InstructorBio = "Prof. Adams is a published novelist and poet. Her debut novel won the National Book Critics Circle Award, and she brings a practitioner's perspective to the workshop.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
        new() { Id = 10, Title = "Shakespeare", Code = "ENG 320", Description = "In-depth study of Shakespeare's major plays and sonnets, exploring themes of power, identity, and language.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. William Harding", InstructorBio = "Dr. Harding is a Renaissance literature scholar with a specialty in early modern drama. He has directed several campus Shakespeare productions.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
        new() { Id = 11, Title = "Molecular Biology", Code = "BIO 201", Description = "Structure and function of DNA, RNA, and proteins. Gene expression, regulation, and modern biotechnology techniques.", Credits = 4, Schedule = "Mon/Wed 10:00–11:20 AM + Lab Thu 1:00–3:50 PM", InstructorName = "Dr. Lisa Okafor", InstructorBio = "Dr. Okafor runs an active research lab studying gene regulation in cancer cells. Students in her course get exposure to cutting-edge molecular techniques.", DepartmentId = 5, DepartmentName = "Biology", IsFeatured = true },
        new() { Id = 12, Title = "Ecology & Evolution", Code = "BIO 310", Description = "Population dynamics, community ecology, natural selection, speciation, and phylogenetics with field study components.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. Mark Sullivan", InstructorBio = "Dr. Sullivan conducts field research in tropical ecosystems. His courses feature immersive field trips to local habitats and nature reserves.", DepartmentId = 5, DepartmentName = "Biology", IsFeatured = false },
    ];

    public IReadOnlyList<Department> GetDepartments() => Departments;

    public Department? GetDepartment(int id) => Departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = Courses.AsEnumerable();

        if (departmentId.HasValue)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public IReadOnlyList<Course> GetFeaturedCourses() => Courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => Courses.FirstOrDefault(c => c.Id == id);

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return GetCourse(request.CourseId) is not null;
    }
}

